class Solution {
public:
    int countBinarySubstrings(string s) {
        int prev = 0, cur = 1, total = 0;
        for (int i = 1; i < (int)s.size(); i++) {
            if (s[i] == s[i - 1]) {
                cur++;
            } else {
                total += min(prev, cur);
                prev = cur;
                cur = 1;
            }
        }
        return total + min(prev, cur);
    }
};
